package net.officefloor.hq.app.setting;

/** The settings form as submitted: the clerk limit (blank: no limit), the floor (blank: 1.00) and the terms in
 *  days (blank: 14) and the late percent
 *  (blank: 0.00) and the policy date (YYYY-MM-DD; blank: the sheet's today) and the period numbering from (YYYY-MM-DD; blank: off) and the terms of grades A, B and C in days (blank: the sheet's terms) and the cap (blank: none) and the proof threshold (blank: none); and the permission matrix entries for open, settle, void, reassign, close and reopen
 *  (comma separated roles; blank: the standing rule); and the grace days (a whole number of days; blank: off; not dated); and the note threshold (blank: none); and the entry date (YYYY-MM-DD; blank: off; not dated); and the grace days of grades A, B and C (blank: none); and the proof thresholds of grades A, B and C (blank: none — the sheet's applies); and the pot (two decimals; blank: none; not dated); and the parent sheet (a sheet's id; blank: none; not dated); and the fiscal year start month (1 to 12; blank: 1; not dated); and the alert threshold (two decimals; blank: off; not dated); and the rounding mode (half-up or half-even; blank: none — a claim rounds by the policy date); and the review threshold (blank: none); and the escalation gap (a whole number of days; blank: off; not dated); and the review SLA (a whole number of days; blank: none; not dated); and the proof kinds (a comma separated list of receipt and photo; blank: none; not dated); a key left out (null) is not changed.
 *  Each setting that carries a figure has its from-date (YYYY-MM-DD; blank or left out: the sheet's today): it is
 *  recorded from that date on. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        String termsA, String termsB, String termsC, String cap, String proofThreshold,
        String clerkLimitFrom, String floorFrom, String termsFrom, String latePctFrom,
        String termsAFrom, String termsBFrom, String termsCFrom, String capFrom, String proofThresholdFrom,
        String permOpen, String permSettle, String permVoid, String permReassign, String permClose, String permReopen,
        String graceDays, String noteThreshold, String noteThresholdFrom, String entryDate,
        String graceA, String graceB, String graceC, String graceAFrom, String graceBFrom, String graceCFrom,
        String proofThresholdA, String proofThresholdB, String proofThresholdC,
        String proofThresholdAFrom, String proofThresholdBFrom, String proofThresholdCFrom, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String roundingFrom,
        String reviewThreshold, String reviewThresholdFrom, String escalateAfter, String reviewSla, String proofKinds) {
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetSetting;

/** The sheet's settings as the screen shows them, each in force on the sheet's today: the clerk limit with two decimals (null: no limit) and the
 *  floor with two decimals, and the terms in days, and the late percent with two decimals, and the policy date (YYYY-MM-DD; "" when
 *  blank: the sheet's today), and the period numbering from (YYYY-MM-DD; "" when off), and the own terms in days of grades A, B and C
 *  ("" when the grade uses the sheet's terms), and the cap with two decimals ("" when there is none), and the proof threshold with two decimals ("" when there is none); and the values recorded
 *  for each dated setting, by key (floor, late-pct, terms, terms-A/B/C, clerk-limit, cap), by from-date; and the permission matrix
 *  entry of each of open, settle, void, reassign, close and reopen (its comma separated roles; "" when blank: the standing rule); and the grace days ("" when off); and the note threshold with two decimals ("" when there is none); and the entry date (YYYY-MM-DD; "" when off); and the grace days of grades A, B and C in force ("" when none); and the proof thresholds of grades A, B and C in force ("" when none); and the pot with two decimals ("" when there is none; not dated); and the parent sheet's id ("" when none; not dated); and the fiscal year start month (1 to 12; not dated); and the alert threshold with two decimals ("" when off; not dated); and the rounding mode in force (half-up or half-even; "" when none); and the review threshold with two decimals ("" when there is none); and the escalation gap in days ("" when off; not dated); and the review SLA in days ("" when none; not dated); and the proof kinds (comma separated; "" when none; not dated). */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, String termsA, String termsB, String termsC, String cap, String proofThreshold,
        Map<String, List<Dated>> dated, String permOpen, String permSettle, String permVoid, String permReassign,
        String permClose, String permReopen, String graceDays, String noteThreshold, String entryDate,
        String graceA, String graceB, String graceC,
        String proofThresholdA, String proofThresholdB, String proofThresholdC, String pot, String parent,
        String fiscalStartMonth, String alertThreshold, String rounding, String reviewThreshold, String escalateAfter, String reviewSla, String proofKinds) {

    /** A value recorded from a date on (null from: the beginning of time; null value: blank). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Sheet sheet) {
        Map<String, List<Dated>> dated = new LinkedHashMap<>();
        for (SheetSetting s : sheet.getSettings()) {
            dated.computeIfAbsent(s.getKey(), k -> new ArrayList<>())
                    .add(new Dated(s.getFromDate() == null ? null : s.getFromDate().toString(), s.getValue()));
        }
        return new SettingsResponse(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                sheet.floorOn(sheet.getToday()).setScale(2).toPlainString(), String.valueOf(sheet.termsOn(sheet.getToday())),
                sheet.latePctOn(sheet.getToday()).setScale(2).toPlainString(),
                sheet.getPolicyDate() == null ? "" : sheet.getPolicyDate().toString(),
                sheet.getPeriodNumberingFrom() == null ? "" : sheet.getPeriodNumberingFrom().toString(),
                gradeTerms(sheet, "A"), gradeTerms(sheet, "B"), gradeTerms(sheet, "C"),
                sheet.getCap() == null ? "" : sheet.getCap().toPlainString(),
                sheet.proofThresholdOn(sheet.getToday()) == null ? "" : sheet.proofThresholdOn(sheet.getToday()).toPlainString(),
                dated, sheet.permOf("open"), sheet.permOf("settle"), sheet.permOf("void"), sheet.permOf("reassign"),
                sheet.permOf("close"), sheet.permOf("reopen"),
                sheet.getGraceDays() == null ? "" : String.valueOf(sheet.getGraceDays()),
                sheet.noteThresholdOn(sheet.getToday()) == null ? "" : sheet.noteThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEntryDate() == null ? "" : sheet.getEntryDate().toString(),
                gradeGrace(sheet, "A"), gradeGrace(sheet, "B"), gradeGrace(sheet, "C"),
                gradeProofThreshold(sheet, "A"), gradeProofThreshold(sheet, "B"), gradeProofThreshold(sheet, "C"),
                sheet.getPot() == null ? "" : sheet.getPot().toPlainString(),
                sheet.getParent() == null ? "" : sheet.getParent(),
                String.valueOf(sheet.getFiscalStartMonth()),
                sheet.getAlertThreshold() == null ? "" : sheet.getAlertThreshold().toPlainString(),
                sheet.roundingOn(sheet.getToday()) == null ? "" : sheet.roundingOn(sheet.getToday()),
                sheet.reviewThresholdOn(sheet.getToday()) == null ? "" : sheet.reviewThresholdOn(sheet.getToday()).toPlainString(),
                sheet.getEscalateAfter() == null ? "" : String.valueOf(sheet.getEscalateAfter()),
                sheet.getReviewSla() == null ? "" : String.valueOf(sheet.getReviewSla()),
                String.join(",", sheet.getProofKinds()));
    }

    /** The grade's grace days in force on the sheet's today; "" when it has none. */
    public static String gradeGrace(Sheet sheet, String grade) {
        Integer grace = sheet.gradeGraceOn(grade, sheet.getToday());
        return grace == null ? "" : String.valueOf(grace);
    }

    /** The grade's proof threshold in force on the sheet's today with two decimals; "" when it has none. */
    public static String gradeProofThreshold(Sheet sheet, String grade) {
        BigDecimal threshold = sheet.gradeProofThresholdOn(grade, sheet.getToday());
        return threshold == null ? "" : threshold.toPlainString();
    }

    /** The grade's own terms in days in force on the sheet's today; "" when it uses the sheet's terms. */
    public static String gradeTerms(Sheet sheet, String grade) {
        Integer terms = sheet.gradeTermsOn(grade, sheet.getToday());
        return terms == null ? "" : String.valueOf(terms);
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.officefloor.hq.app.claim.ProofKind;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the settings form from the body; refuses a clerk limit or floor that is negative or has more than two
 *  decimals, and terms that are not a whole number of days, and a late percent that is negative or has more than two decimals, and a policy date or period numbering from that is not a calendar date
 *  (YYYY-MM-DD). A blank clerk limit means no limit; a blank floor is
 *  1.00; blank terms are 14; a blank late percent is 0.00; a blank policy date is the sheet's today; a blank period numbering from is off; a blank entry date is off; a blank cap is none (else an amount like the floor); a blank proof threshold is none (else an amount like the floor); a blank note threshold is none (else an amount like the floor). A grade's terms must be a whole number of days, or blank (the grade uses the sheet's terms). A permission matrix entry must be a comma separated list of
 *  roles (clerk, steward), or blank (the standing rule). The grace days must be a whole number of days, or blank (off). A grade's grace days must be a whole number of days, or blank (none). A grade's proof threshold is an amount like the floor, or blank (none: the sheet's applies). The pot is an amount like the floor, or blank (none); not dated. The fiscal year start month is a month 1 to 12, or blank (1); not dated. The alert threshold is an amount like the floor, or blank (off); not dated. The rounding mode is half-up or half-even, or blank (none); dated. A blank review threshold is none (else an amount like the floor); dated. The escalation gap must be a whole number of days, or blank (off); not dated. The proof kinds are a comma separated list of receipt and photo, or blank (none); not dated. A key left out is not changed.
 *  A from-date must be a calendar date (YYYY-MM-DD), or blank (the sheet's today). */
public class ValidateSettings {

    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    private static final Pattern MONTH = Pattern.compile("\\d{1,2}");

    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body) throws InvalidSettingsException {
        List<SettingsInput.Change> changes = new ArrayList<>();
        if (request != null) {
            amount(changes, Sheet.CLERK_LIMIT, request.clerkLimit(), null, request.clerkLimitFrom(),
                    "The clerk limit must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.FLOOR, request.floor(), Sheet.DEFAULT_FLOOR, request.floorFrom(),
                    "The floor must be an amount, 0.00 or more, with up to two decimals, or blank.");
            days(changes, Sheet.TERMS, request.terms(), Sheet.DEFAULT_TERMS, request.termsFrom(),
                    "The terms must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.LATE_PCT, request.latePct(), Sheet.DEFAULT_LATE_PCT, request.latePctFrom(),
                    "The late percent must be a percent, 0.00 or more, with up to two decimals, or blank.");
            date(changes, "policy-date", request.policyDate(), "The policy date must be a date (YYYY-MM-DD), or blank.");
            date(changes, "period-numbering-from", request.periodNumberingFrom(),
                    "The period numbering from must be a date (YYYY-MM-DD), or blank.");
            date(changes, Sheet.ENTRY_DATE, request.entryDate(), "The entry date must be a date (YYYY-MM-DD), or blank.");
            days(changes, Sheet.TERMS + "-A", request.termsA(), null, request.termsAFrom(),
                    "The terms of grade A must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-B", request.termsB(), null, request.termsBFrom(),
                    "The terms of grade B must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.TERMS + "-C", request.termsC(), null, request.termsCFrom(),
                    "The terms of grade C must be a whole number of days, 0 or more, or blank.");
            amount(changes, Sheet.CAP, request.cap(), null, request.capFrom(),
                    "The cap must be an amount, 0.00 or more, with up to two decimals, or blank.");
            amount(changes, Sheet.PROOF_THRESHOLD, request.proofThreshold(), null, request.proofThresholdFrom(),
                    "The proof threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            roles(changes, "open", request.permOpen());
            roles(changes, "settle", request.permSettle());
            roles(changes, "void", request.permVoid());
            roles(changes, "reassign", request.permReassign());
            roles(changes, "close", request.permClose());
            roles(changes, "reopen", request.permReopen());
            graceDays(changes, request.graceDays());
            amount(changes, Sheet.NOTE_THRESHOLD, request.noteThreshold(), null, request.noteThresholdFrom(),
                    "The note threshold must be an amount, 0.00 or more, with up to two decimals, or blank.");
            days(changes, Sheet.graceKey("A"), request.graceA(), null, request.graceAFrom(),
                    "The grace days of grade A must be a whole number of days, 0 or more, or blank.");
            days(changes, Sheet.graceKey("B"), request.graceB(), null, request.graceBFrom(),
