395	/** Sets the settings the form sets: a setting that carries a figure (the clerk limit, floor, terms, late percent,
396	 *  each grade's own terms, cap, proof threshold, note threshold, each grade's grace days, each grade's proof threshold, review threshold) is recorded from its from-date (the sheet's today when none is given), replacing a
397	 *  value recorded from that date and keeping the others; the policy date, period numbering from and entry date are set; a permission matrix entry
398	 *  (key perm-<action>), the grace days, the pot, the parent sheet, the fiscal year start month and the alert threshold and the escalation gap and the review SLA and the proof kinds are recorded undated. Each is logged with the sheet's today (so the
399	 *  settings can be worked out as they stood on an earlier date). */
400	public class ApplySettings {
401	    public void apply(@Val SettingsInput input, @Val Sheet sheet, SheetRepository repository, SettingLogRepository log) {
402	        for (SettingsInput.Change change : input.changes()) {
403	            LocalDate from = null;
404	            if (change.dated()) {
405	                from = change.from() != null ? change.from() : sheet.getToday();
406	                sheet.record(change.key(), from, change.value());
407	            } else if (change.key().startsWith("perm-") || Sheet.GRACE_DAYS.equals(change.key())
408	                    || Sheet.ESCALATE_AFTER.equals(change.key()) || Sheet.REVIEW_SLA.equals(change.key())
409	                    || Sheet.PROOF_KINDS.equals(change.key())
410	                    || Sheet.POT.equals(change.key()) || Sheet.PARENT.equals(change.key())
411	                    || Sheet.FISCAL_START_MONTH.equals(change.key())
412	                    || Sheet.ALERT_THRESHOLD.equals(change.key())) {
413	                sheet.record(change.key(), null, change.value());
414	            } else if (Sheet.POLICY_DATE.equals(change.key())) {
415	                sheet.setPolicyDate(change.value() == null ? null : LocalDate.parse(change.value()));
416	            } else if (Sheet.PERIOD_NUMBERING_FROM.equals(change.key())) {
417	                sheet.setPeriodNumberingFrom(change.value() == null ? null : LocalDate.parse(change.value()));
418	            } else if (Sheet.ENTRY_DATE.equals(change.key())) {
419	                sheet.setEntryDate(change.value() == null ? null : LocalDate.parse(change.value()));
420	            } else {
421	                continue;
422	            }
423	            log.save(new SettingLog(sheet.getId(), change.key(), from, change.value(), sheet.getToday()));
424	        }
425	        repository.saveAndFlush(sheet);
426	        log.flush();
427	    }
428	}
